TWComponent.script:
//log.error("*** Input: " + tw.local.input);
//java.lang.Thread.sleep(500); //Simulate latency so we have a chance to see the refresh button spin :)

tw.local.dataSeries = new tw.object.DataSeries();

tw.local.dataSeries.seriesName = "Sample";
tw.local.dataSeries.dataPoints = new tw.object.listOf.DataPoint();

var i = 0;

tw.local.dataSeries.dataPoints[i] = new tw.object.DataPoint();
tw.local.dataSeries.dataPoints[i].value = Math.floor(10 * Math.random());
tw.local.dataSeries.dataPoints[i].label = "Category " + i;
i++;
tw.local.dataSeries.dataPoints[i] = new tw.object.DataPoint();
tw.local.dataSeries.dataPoints[i].value = 3;
tw.local.dataSeries.dataPoints[i].label = "Category " + i;
i++;
tw.local.dataSeries.dataPoints[i] = new tw.object.DataPoint();
tw.local.dataSeries.dataPoints[i].value = Math.floor(35 * Math.random());
tw.local.dataSeries.dataPoints[i].label = "Category " + i;
i++;
tw.local.dataSeries.dataPoints[i] = new tw.object.DataPoint();
tw.local.dataSeries.dataPoints[i].value = 23;
tw.local.dataSeries.dataPoints[i].label = "Category " + i;
i++;
tw.local.dataSeries.dataPoints[i] = new tw.object.DataPoint();
tw.local.dataSeries.dataPoints[i].value = 18;
tw.local.dataSeries.dataPoints[i].label = "Category " + i;
i++;

